class WordDictionary {
private:
    struct TrieNode {
        TrieNode* children[26] = {nullptr};
        bool isEnd = false;
    };
    TrieNode* root;

    bool dfs(TrieNode* node, const string& word, int i) {
        if (!node) return false;
        if (i == (int)word.size()) return node->isEnd;
        char ch = word[i];
        if (ch == '.') {
            for (int c = 0; c < 26; ++c) {
                if (node->children[c] && dfs(node->children[c], word, i + 1)) {
                    return true;
                }
            }
            return false;
        } else {
            int idx = ch - 'a';
            return dfs(node->children[idx], word, i + 1);
        }
    }

public:
    WordDictionary() {
        root = new TrieNode();
    }

    void addWord(string word) {
        TrieNode* curr = root;
        for (char ch : word) {
            int idx = ch - 'a';
            if (!curr->children[idx]) {
                curr->children[idx] = new TrieNode();
            }
            curr = curr->children[idx];
        }
        curr->isEnd = true;
    }

    bool search(string word) {
        return dfs(root, word, 0);
    }
};

class WordDictionary {
    private static class Node {
        Node[] children = new Node[26];
        boolean isEnd = false;
    }
    private final Node root = new Node();

    public WordDictionary() {}

    public void addWord(String word) {
        Node curr = root;
        for (char ch : word.toCharArray()) {
            int idx = ch - 'a';
            if (curr.children[idx] == null) {
                curr.children[idx] = new Node();
            }
            curr = curr.children[idx];
        }
        curr.isEnd = true;
    }

    public boolean search(String word) {
        return dfs(root, word, 0);
    }

    private boolean dfs(Node node, String word, int i) {
        if (node == null) return false;
        if (i == word.length()) return node.isEnd;
        char ch = word.charAt(i);
        if (ch == '.') {
            for (Node child : node.children) {
                if (child != null && dfs(child, word, i + 1)) return true;
            }
            return false;
        }
        return dfs(node.children[ch - 'a'], word, i + 1);
    }
}

var WordDictionary = function() {
    this.root = {};
};

WordDictionary.prototype.addWord = function(word) {
    let curr = this.root;
    for (const ch of word) {
        if (!curr[ch]) curr[ch] = {};
        curr = curr[ch];
    }
    curr.isEnd = true;
};

WordDictionary.prototype.search = function(word) {
    const dfs = (node, i) => {
        if (i === word.length) return Boolean(node.isEnd);
        const ch = word[i];
        if (ch === '.') {
            for (const key of Object.keys(node)) {
                if (key !== 'isEnd' && dfs(node[key], i + 1)) return true;
            }
            return false;
        }
        if (!node[ch]) return false;
        return dfs(node[ch], i + 1);
    };
    return dfs(this.root, 0);
};
